globalThis.ANDE_CHUNKS["cebf364e4540dae96839000dfbd46ab0daf6dd1ad7860b6a9d76184094a0dead"] = [{"id":"tencent:-2","sourceKey":"tencent","company":"腾讯","title":"项目实习生-技术","city":"深圳总部 ","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=-2","duty":"本岗位为项目制实习生招聘，你将协助项目团队完成短期的技术类工作支持。\n\n划分为以下方向：\n（1）软件开发：后台开发、客户端开发、游戏客户端开发、测试开发、运营开发、前端开发、全栈开发、数据工程等；\n（2）技术研究：机器学习、计算机视觉、多媒体处理、自然语言处理、机器人、计算机图形学、数据科学等；\n（3）技术运营；\n（4）测试与质量管理。","requirements":"我们期望你：\n1. 具备编程能力，掌握C/C++/Java/Go/PHP/JavaScript/Python等其中一门编程语言。\n2. 具有一定的学习能力、分析及解决问题能力，有责任心与合作意识","description":"岗位描述\n本岗位为项目制实习生招聘，你将协助项目团队完成短期的技术类工作支持。\n\n划分为以下方向：\n（1）软件开发：后台开发、客户端开发、游戏客户端开发、测试开发、运营开发、前端开发、全栈开发、数据工程等；\n（2）技术研究：机器学习、计算机视觉、多媒体处理、自然语言处理、机器人、计算机图形学、数据科学等；\n（3）技术运营；\n（4）测试与质量管理。\n\n岗位要求\n我们期望你：\n1. 具备编程能力，掌握C/C++/Java/Go/PHP/JavaScript/Python等其中一门编程语言。\n2. 具有一定的学习能力、分析及解决问题能力，有责任心与合作意识\n\n软件开发类\n\n项目实习生-全栈开发\nCDG\n企业发展事业群\n\n腾讯金融科技\n腾讯金融科技（Tencent Financial Technology）是腾讯公司提供移动支付与金融服务的综合业务平台。我们始终秉承合规、风控、开放、有所为有所不为","jdComplete":false,"sourceStatus":null},{"id":"tencent:-3","sourceKey":"tencent","company":"腾讯","title":"项目实习生-产品","city":"深圳总部 上海 北京 ","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=-3","duty":"本岗位为项目制实习生招聘，你将协助项目团队完成短期的产品或内容类工作支持。\n\n划分为以下方向：\n（1）产品：产品策划/运营等；\n（2）游戏产品：游戏策划、游戏发行/运营等；\n（3）内容：内容运营、内容创作、制片人助理等。","requirements":"我们期望你：\n1. 具有一定的逻辑思维能力、学习能力与文字组织能力\n2. 具有良好的沟通能力与执行力，有责任心与合作意识\n3. 对互联网产品有观察和认知","description":"岗位描述\n本岗位为项目制实习生招聘，你将协助项目团队完成短期的产品或内容类工作支持。\n\n划分为以下方向：\n（1）产品：产品策划/运营等；\n（2）游戏产品：游戏策划、游戏发行/运营等；\n（3）内容：内容运营、内容创作、制片人助理等。\n\n岗位要求\n我们期望你：\n1. 具有一定的逻辑思维能力、学习能力与文字组织能力\n2. 具有良好的沟通能力与执行力，有责任心与合作意识\n3. 对互联网产品有观察和认知\n\n游戏产品类\n\n项目实习生-游戏运营\nIEG\n互动娱乐事业群\n\n游戏国际发行 Level Infinite\nLevel Infinite，作为腾讯国际游戏业务的整体品牌，致力于为全球玩家带来高品质的互动娱乐体验，让玩家随时随地可享受畅快游戏带来的乐趣。我们携手旗下工作室为全球用户带来了超过20款游戏，覆盖200多个国家和地区，其中《PUBG Mobile》《NIKKE》《Tower of Fanta","jdComplete":false,"sourceStatus":null},{"id":"tencent:-4","sourceKey":"tencent","company":"腾讯","title":"项目实习生-设计","city":"深圳总部 ","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=-4","duty":"本岗位为项目制实习生招聘，你将协助项目团队完成短期的设计或游戏美术类工作支持。\n\n划分为以下方向：\n（1）设计：视觉设计、交互设计、多媒体设计、用户研究等；\n（2）游戏美术：2D角色与场景设计、3D角色与场景设计、动画、特效、技术美术等。","requirements":"我们期望你：\n1. 掌握常见美术及设计软件的使用方法\n2. 具有一定的审美能力，有美术或设计相关专业知识储备\n3. 具有良好的沟通能力与执行力，有责任心与合作意识","description":"岗位描述\n本岗位为项目制实习生招聘，你将协助项目团队完成短期的设计或游戏美术类工作支持。\n\n划分为以下方向：\n（1）设计：视觉设计、交互设计、多媒体设计、用户研究等；\n（2）游戏美术：2D角色与场景设计、3D角色与场景设计、动画、特效、技术美术等。\n\n岗位要求\n我们期望你：\n1. 掌握常见美术及设计软件的使用方法\n2. 具有一定的审美能力，有美术或设计相关专业知识储备\n3. 具有良好的沟通能力与执行力，有责任心与合作意识\n\n游戏美术类\n\n项目实习生-动画\nIEG\n互动娱乐事业群\n\n游戏前沿技术\n游戏前沿技术，聚焦腾讯游戏技术预研和实现，通过提供产品化服务来提升整体游戏研发效率，助力腾讯成为全球游戏研发技术领先者。行业技术大牛及全球顶尖院校大咖云集于此，我们着眼于「人工智能技术」与游戏研发深入结合，探索新玩法和交互方式；引入AIGC、图形学、程序化内容生成、动捕等前沿技术，提升「数字内容」制","jdComplete":false,"sourceStatus":null},{"id":"tencent:-5","sourceKey":"tencent","company":"腾讯","title":"项目实习生-市场","city":"深圳总部 北京 上海 广州 ","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=-5","duty":"本岗位为项目制实习生招聘，你将协助项目团队完成短期的市场、销售等支持工作。\r\n\r\n划分为以下方向：\r\n（1）市场：市场研究、商业分析等；\r\n（2）销售：商务拓展等。","requirements":"我们期望你：\r\n1、有一定的市场意识，了解市场动态和新事物。\r\n2、工作主动，具有较好的人际沟通技巧，协调能力，擅于合作。\r\n3、掌握日常办公软件及办公设备的使用方法。\r\n4、理解力好，具有较好的沟通与协调能力，责任心与执行力强。","description":"岗位描述\n本岗位为项目制实习生招聘，你将协助项目团队完成短期的市场、销售等支持工作。\r\n\r\n划分为以下方向：\r\n（1）市场：市场研究、商业分析等；\r\n（2）销售：商务拓展等。\n\n岗位要求\n我们期望你：\r\n1、有一定的市场意识，了解市场动态和新事物。\r\n2、工作主动，具有较好的人际沟通技巧，协调能力，擅于合作。\r\n3、掌握日常办公软件及办公设备的使用方法。\r\n4、理解力好，具有较好的沟通与协调能力，责任心与执行力强。\n\n战略投资类\n\n项目实习生-商业分析\nCDG\n企业发展事业群\n\n腾讯战略发展部\n腾讯战略发展部是一支洞悉行业发展趋势的精锐队伍。作为管理层的智囊团，推动公司在前沿领域如人工智能、机器人、量子计算、智慧医疗、可持续社会价值、碳中和等领域的战略布局；作为公司战略驱动者，深入社交、游戏、视频、音乐、安全等业务，解决难题，实现突破；作为腾讯生态公司的合作伙伴，为共同的健康繁荣发展提供专","jdComplete":false,"sourceStatus":null},{"id":"tencent:-6","sourceKey":"tencent","company":"腾讯","title":"项目实习生-职能","city":"深圳总部 北京 上海 广州 成都 ","category":"职能","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=-6","duty":"本岗位为项目制实习生招聘，你将协助项目团队完成短期的行政、财经、HR等支持工作。\r\n\r\n划分为以下方向：\r\n（1）行政方向；\r\n（2）财经方向；\r\n（3）人力资源方向。","requirements":"我们期望你：\r\n1、工作主动，具有较好的人际沟通技巧，协调能力，擅于合作。\r\n2、掌握日常办公软件及办公设备的使用方法。\r\n3、理解力好，具有较好的沟通与协调能力，责任心与执行力强。","description":"岗位描述\n本岗位为项目制实习生招聘，你将协助项目团队完成短期的行政、财经、HR等支持工作。\r\n\r\n划分为以下方向：\r\n（1）行政方向；\r\n（2）财经方向；\r\n（3）人力资源方向。\n\n岗位要求\n我们期望你：\r\n1、工作主动，具有较好的人际沟通技巧，协调能力，擅于合作。\r\n2、掌握日常办公软件及办公设备的使用方法。\r\n3、理解力好，具有较好的沟通与协调能力，责任心与执行力强。\n\n人力资源类\n\n项目实习生-人力资源\nS3\n职能系统－HR与管理线\n\n腾讯HR与管理线\nS3职能系统-HR与管理线，秉承“用户为根，员工为本”的理念，主要负责腾讯人力资源各项职能，以HR三支柱的组织模式，采用“服务产品化、管理市场化”的方法，并在AI时代下大力探索未来管理模式和创新管理实践，以全面支撑腾讯组织、人才、文化的发展，助力公司业务和人才的共同成长。\n\n【关于腾讯AI-HR Star项目】\n腾讯校招人力资源培训生","jdComplete":false,"sourceStatus":null},{"id":"tencent:1153452731391100928","sourceKey":"tencent","company":"腾讯","title":"解决方案-行业咨询方向","city":"深圳总部/上海","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1153452731391100928","duty":"1、学习和理解技术、产品及应用场景，挖掘和引导客户需求，结合腾讯平台能力为客户提供解决方案；\n2、深度参与产品架构设计、售前咨询、项目交付、售后服务其中一个或多个环节，保障解决方案落地，解决客户问题，助力客户成功；\n3、学习解决方案的最佳实践，并通过实战经验的积累，沉淀面向企业数字化转型的通用方案能力与优势；\n4、保持市场洞察，感知行业动态，不断提升公司产品和解决方案的行业竞争力。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n理工科专业，熟悉云计算、大数据、人工智能等技术优先。\n\n其他：\n1、具有出色的书面和口头沟通能力、人际沟通能力，富有创造性、灵活性及自信心；\n2、具备快速学习能力，能够快速获取、整理及分析信息，逻辑性强，具有良好的商业意识和客户服务意识；\n3、目标感强，自我驱动，以结果为导向，能接受出差。","description":"你将在充满机遇与挑战的工作中，  成为客户与技术产品间的桥梁，  为产业发展提供多元价值。  深耕产业，拥抱未来！\n\n岗位描述\n1、学习和理解技术、产品及应用场景，挖掘和引导客户需求，结合腾讯平台能力为客户提供解决方案；\n2、深度参与产品架构设计、售前咨询、项目交付、售后服务其中一个或多个环节，保障解决方案落地，解决客户问题，助力客户成功；\n3、学习解决方案的最佳实践，并通过实战经验的积累，沉淀面向企业数字化转型的通用方案能力与优势；\n4、保持市场洞察，感知行业动态，不断提升公司产品和解决方案的行业竞争力。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n理工科专业，熟悉云计算、大数据、人工智能等技术优先。\n\n其他：\n1、具有出色的书面和口头沟通能力、人际沟通能力，富有创造性、灵活性及自信","jdComplete":false,"sourceStatus":null},{"id":"tencent:1153452731391100929","sourceKey":"tencent","company":"腾讯","title":"CSIG技术产品商务培训生","city":"西安/深圳总部/北京/上海/广州/杭州/南京/厦门/中国香港","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1153452731391100929","duty":"加入“技术产品商务培训生”人才专项，你将成为腾讯产业互联网团队重要的一员，面向国内外各机构、企业组织和个人开发者，推广腾讯云的核心产品和解决方案，同时综合直销和渠道分销等形式，挖掘潜在商机、助力团队共同实现业务目标。\n作为CSIG的技术产品商务培训生，你将有机会代表公司深度参与完整的客户业务合作全过程，完成深度的行业洞察、挖掘商机客群、制定和参与全方位的云与技术解决方案等。\n此外，还将收获在一线的完整实践体验和个人的快速提升及成长。","requirements":"1、计算机、信息技术、计算机交叉学科等相关专业背景优先，商科专业背景同时愿意快速学习技术产品知识的同学；\n2、具备良好的综合素质，有优秀的沟通和团队协作能力、热爱挑战，能在复杂环境中探索解决路径；\n3、愿意将“给客户提供优秀的技术产品，并达成商务目标”作为个人职业发展方向；\n4、积极拥抱云、大数据、人工智能等技术产品领域的变化，具备快速学习能力及敏锐的市场洞察意识。","description":"一起投身到产业互联网浪潮中，  以领先数字平台产品点亮智慧未来，  遇见坚定稳步成长的自己！\n\n岗位描述\n加入“技术产品商务培训生”人才专项，你将成为腾讯产业互联网团队重要的一员，面向国内外各机构、企业组织和个人开发者，推广腾讯云的核心产品和解决方案，同时综合直销和渠道分销等形式，挖掘潜在商机、助力团队共同实现业务目标。\n作为CSIG的技术产品商务培训生，你将有机会代表公司深度参与完整的客户业务合作全过程，完成深度的行业洞察、挖掘商机客群、制定和参与全方位的云与技术解决方案等。\n此外，还将收获在一线的完整实践体验和个人的快速提升及成长。\n\n岗位要求\n1、计算机、信息技术、计算机交叉学科等相关专业背景优先，商科专业背景同时愿意快速学习技术产品知识的同学；\n2、具备良好的综合素质，有优秀的沟通和团队协作能力、热爱挑战，能在复杂环境中探索解决路径；\n3、愿意将“给客户提供优秀的技术产品，并达成商","jdComplete":false,"sourceStatus":null},{"id":"tencent:1153452731391100930","sourceKey":"tencent","company":"腾讯","title":"项目管理","city":"深圳总部/上海","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1153452731391100930","duty":"1、参与项目的管理与统筹，帮助团队合理的理解、判断需求及方向，并进行内外资源的部署，推动项目和需求的落地，确保高效达成项目目标；\n2、协助合理规划项目和相关团队及合作机制，把控项目进度，风险预警、资源配置，关注合作细节，推动解决问题，并协助项目的复盘和总结；\n3、协助优化团队资源结构，进行需求、人力、成本的分析，负责制定和优化工作流程，运用数字化工具和AI辅助项目管理（智能排期、风险预测、自动化报告等），将人工推进事务逐步标准化、流程化、智能化。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n了解项目开发过程、敏捷项目管理理论。\n\n其他：\n1、乐观开朗、善于沟通、擅长协作、乐于用自己的能量感染他人；\n2、拥有明确的职业规划，立足于项目管理岗位长期发展。\n3、对AI辅助项目管理工具和方法有兴趣，愿意探索项目管理智能化的可能性。","description":"项目的达成需要你的推动与把控，\n你是项目推进的“大总管”，也是推动项目实现的多面手！\n\n岗位描述\n1、参与项目的管理与统筹，帮助团队合理的理解、判断需求及方向，并进行内外资源的部署，推动项目和需求的落地，确保高效达成项目目标；\n2、协助合理规划项目和相关团队及合作机制，把控项目进度，风险预警、资源配置，关注合作细节，推动解决问题，并协助项目的复盘和总结；\n3、协助优化团队资源结构，进行需求、人力、成本的分析，负责制定和优化工作流程，运用数字化工具和AI辅助项目管理（智能排期、风险预测、自动化报告等），将人工推进事务逐步标准化、流程化、智能化。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n了解项目开发过程、敏捷项目管理理论。\n\n其他：\n1、乐观开朗、善于沟通、擅长协作、乐于用自己的能量","jdComplete":false,"sourceStatus":null},{"id":"tencent:1153452731391100931","sourceKey":"tencent","company":"腾讯","title":"行业运营","city":"深圳总部/北京/上海/广州","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1153452731391100931","duty":"1、扫描行业市场、关注行业前沿动态、分析行业产业结构、识别行业新机会点，洞察商业模式变化趋势和探索新的商业模式，通过对市场的深入分析，了解产品在行业中的定位与价值，促进业务发展；\n2、 通过行业目标客户圈定和特点分析，发现和跟踪商机、深入分析客户需求和应用场景，提供解决方案和产品能力并推动实施，使产品具备较好的商业交付能力；\n3、协调公司内外部资源达成目标，内部衔接销售、产品，外部衔接客户、服务商等，建立行业作战地图，并跟踪客户转化和渗透提升，不断提升客户价值，积累大客户标杆，驱动整体目标的达成；\n4、协同业务团队战略规划，明确经营指标体系建设，周期性经营指标分析及报告数据输出，进行KPI达成情况和机会及风险的分析，建立业务风险预警机制。","requirements":"1、 本科及以上学历，热爱互联网行业；\n2、 具备优秀的分析问题、解决问题、信息整合、数据挖掘、逻辑组织和观点提炼能力；有一定方案撰写和excel建模能力；\n3、 良好的沟通能力和团队合作精神。","description":"你将作为连接市场与产品的桥梁，\n互联网的市场先锋、业务发展的“啄木鸟”。\n下一个伟大，由你开始！\n\n岗位描述\n1、扫描行业市场、关注行业前沿动态、分析行业产业结构、识别行业新机会点，洞察商业模式变化趋势和探索新的商业模式，通过对市场的深入分析，了解产品在行业中的定位与价值，促进业务发展；\n2、 通过行业目标客户圈定和特点分析，发现和跟踪商机、深入分析客户需求和应用场景，提供解决方案和产品能力并推动实施，使产品具备较好的商业交付能力；\n3、协调公司内外部资源达成目标，内部衔接销售、产品，外部衔接客户、服务商等，建立行业作战地图，并跟踪客户转化和渗透提升，不断提升客户价值，积累大客户标杆，驱动整体目标的达成；\n4、协同业务团队战略规划，明确经营指标体系建设，周期性经营指标分析及报告数据输出，进行KPI达成情况和机会及风险的分析，建立业务风险预警机制。\n\n岗位要求\n1、 本科及以上学历，热爱互联","jdComplete":false,"sourceStatus":null},{"id":"tencent:1155545119882220544","sourceKey":"tencent","company":"腾讯","title":"投资分析","city":"北京","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1155545119882220544","duty":"1、Lead industry and economic research activities with a focus on the Internet field;\n2、Participate and contribute in deal sourcing, evaluation, due diligence and deal execution process\n3、Participate and contribute in post deal company research activities\n4、Enhance and maintain the team's knowledge base","requirements":"1、Strong interest, passion, and business sense for Internet, investment and Tencent\n2、High level of integrity, dedication and motivation\n3、Bachelor/Master degree from top schools; All majors are welcomed\n4、Excellent problem solving skills; Solid critical thinking skills\n5、Fluency in English and Chinese\n6、Internship experience with top consulting firms and/or investment banks is a strong plus","description":"You are a key player in connecting investment decisions with market dynamics. Here, you will apply your insight and judgment to provide objective and accurate investment advice.\n\n岗位描述\n1、Lead industry and economic research activities with a focus on the Internet field;\n2、Participate and contribute in deal sourcing, evaluation, due diligence and deal execution process\n3、Participate and contribute in","jdComplete":false,"sourceStatus":null},{"id":"tencent:1155545119882220545","sourceKey":"tencent","company":"腾讯","title":"投资分析(技术方向)","city":"北京","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1155545119882220545","duty":"1、主导以科技领域为主的行业及经济研究工作；\n2、参与并助力项目搜寻、评估、尽职调查及交易执行全流程；\n3、参与并助力交易完成后的标的公司研究工作；\n4、完善并维护团队的知识库体系。","requirements":"1、对科技投资领域及腾讯业务具有浓厚兴趣、热情及商业洞察力；\n2、理工科专业背景，包括但不限于：计算机科学与技术、电子信息工程、数学与统计学、数据科学与大数据技术、微电子学与集成电路、电子科学与技术、材料科学与工程、物理学等技术类专业；\n3、具备高度诚信、敬业精神与自我驱动力；\n4、出色的解决问题能力，具备扎实的批判性思维；\n5、中英文流利。","description":"这是一个连接投资决策与市场动态的关键角色。在这里，你将运用自己的洞察力和判断力，提供客观且精准的投资建议。\n\n岗位描述\n1、主导以科技领域为主的行业及经济研究工作；\n2、参与并助力项目搜寻、评估、尽职调查及交易执行全流程；\n3、参与并助力交易完成后的标的公司研究工作；\n4、完善并维护团队的知识库体系。\n\n岗位要求\n1、对科技投资领域及腾讯业务具有浓厚兴趣、热情及商业洞察力；\n2、理工科专业背景，包括但不限于：计算机科学与技术、电子信息工程、数学与统计学、数据科学与大数据技术、微电子学与集成电路、电子科学与技术、材料科学与工程、物理学等技术类专业；\n3、具备高度诚信、敬业精神与自我驱动力；\n4、出色的解决问题能力，具备扎实的批判性思维；\n5、中英文流利。\n\n加分项或注意事项\n本岗位需上传PDF格式简历。\n\n本岗位需上传PDF格式简历。\n\nCDG\n企业发展事业群\n\n腾讯投资\n腾讯投资成立于20","jdComplete":false,"sourceStatus":null},{"id":"tencent:1165235557480470528","sourceKey":"tencent","company":"腾讯","title":"秘书","city":"深圳总部/北京/成都","category":"职能","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1165235557480470528","duty":"1、负责部门管理者的日程管理、会议支持、差旅支持等工作，并协助管理者做好部门管理及团队融合；\n2、担任部门内各项职能类工作接口人，包括行政、人事、采购、资产、费用、合同、文档、资料管理等，统筹管理相关事务；\n3、根据部门管理要求，协助制定并实施部门级管理规章制度及各项流程，并定期优化；\n4、负责部门文化建设，结合组织需求，通过活动组织、氛围建设、荣誉激励等方式建立良好的组织氛围，提升组织活力；\n5、及时传达公司下发的各类管理规定及要求，保障管理要求在部门的落地；\n6、参与体系级活动组织，协助体系组织建设及文化落地。","requirements":"1、本科及以上学历；\n2、热情开朗，为人正直，具备高效执行力，抗压性强，具备良好的时间管理、情绪管理及沟通能力；\n3、具备优秀的服务意识、高度责任感及团队合作精神，能够与同事保持良好的工作关系；\n4、工作例行化程度高，做事清晰有条理，具有全局观及项目预见性、前瞻意识；\n5、熟练运用各种日常办公软件及办公设备，能独立组织大型团队活动并有创新意识。","description":"你是部门里的重要担当，\n你眼观六路，大事小事，都放心上。\n你耳听八方，一切细节，尽在把握。\n你聚合团队，温暖人心。\n有你，更有爱！\n\n岗位描述\n1、负责部门管理者的日程管理、会议支持、差旅支持等工作，并协助管理者做好部门管理及团队融合；\n2、担任部门内各项职能类工作接口人，包括行政、人事、采购、资产、费用、合同、文档、资料管理等，统筹管理相关事务；\n3、根据部门管理要求，协助制定并实施部门级管理规章制度及各项流程，并定期优化；\n4、负责部门文化建设，结合组织需求，通过活动组织、氛围建设、荣誉激励等方式建立良好的组织氛围，提升组织活力；\n5、及时传达公司下发的各类管理规定及要求，保障管理要求在部门的落地；\n6、参与体系级活动组织，协助体系组织建设及文化落地。\n\n岗位要求\n1、本科及以上学历；\n2、热情开朗，为人正直，具备高效执行力，抗压性强，具备良好的时间管理、情绪管理及沟通能力；\n3、具备","jdComplete":false,"sourceStatus":null},{"id":"tencent:1165235572529633280","sourceKey":"tencent","company":"腾讯","title":"设施设备管理","city":"深圳总部","category":"职能","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1165235572529633280","duty":"1、项目管理：协助完成集团机电相关工程系统质量检查、验收；\n2、设施管理：管理集团在用项目机电相关设施设备；\n3、供应商管理：负责供应商管理、暖通专业合同管理，工程预算、验收及问题判断。","requirements":"1、本科及以上学历，建筑环境与能源应用工程等相关专业优先；\n2、掌握CAD等制图软件，对国家施工规范有一定了解。","description":"加入腾讯，让世界看到你的影响力！\n\n岗位描述\n1、项目管理：协助完成集团机电相关工程系统质量检查、验收；\n2、设施管理：管理集团在用项目机电相关设施设备；\n3、供应商管理：负责供应商管理、暖通专业合同管理，工程预算、验收及问题判断。\n\n岗位要求\n1、本科及以上学历，建筑环境与能源应用工程等相关专业优先；\n2、掌握CAD等制图软件，对国家施工规范有一定了解。\n\n有设计院或工程施工单位实习经验优先。\n\nS1\n职能系统－职能线\n\n腾讯职能线\nS1职能系统-职能线，秉持“用户为本，科技向善”的理念，以“守护底线，服务发展，筑牢可靠大后方，彰显向善价值观”为定位，全面支撑腾讯公共事务、法务、安全、腾讯研究、行政、基建、采购等多个职能领域，用专业能力支持业务发展。","jdComplete":false,"sourceStatus":null},{"id":"tencent:1177660287760077824","sourceKey":"tencent","company":"腾讯","title":"视觉设计","city":"深圳总部/北京/广州","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1177660287760077824","duty":"1、负责参与公司产品的视觉内容，包括UI、多媒体、品牌等设计，具备一定的跨平台及多终端设计能力；\n2、负责产品前期的概念创意，整体视觉风格的制定，推动产品实现及进行阶段性的品牌推广；\n3、负责制定设计标准及规范，保障产品体验及设计的一致性；\n4、有较好的用户体验思维，熟练使用AIGC创意工具辅助设计探索和生产，具备较强的能力扩展性。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、专业执行力：美术、设计相关专业本科或研究生，能够熟练使用Photoshop、Figma、After Effects、Illustrator、Sketch等软件；综合素质扎实，热爱设计行业；\n2、对主流AIGC设计工具有使用经验或强烈的学习兴趣，能独立思考AI如何提升设计效率与创意质量。\n\n\n其他：\n1、持续学习力：富于创新、思维灵活，并对先进的设计理念和技术有较强的理解能力；有一定的设计理论知识和对流行趋势敏锐的洞察力；\n2、团队协作力：具有良好的沟通能力和团队协作精神。","description":"在这里，\n你的设计意味着触动亿万人的情感和引领互联网时尚潮流。\n设计，不止于此！\n\n岗位描述\n1、负责参与公司产品的视觉内容，包括UI、多媒体、品牌等设计，具备一定的跨平台及多终端设计能力；\n2、负责产品前期的概念创意，整体视觉风格的制定，推动产品实现及进行阶段性的品牌推广；\n3、负责制定设计标准及规范，保障产品体验及设计的一致性；\n4、有较好的用户体验思维，熟练使用AIGC创意工具辅助设计探索和生产，具备较强的能力扩展性。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、专业执行力：美术、设计相关专业本科或研究生，能够熟练使用Photoshop、Figma、After Effects、Illustrator、Sketch等软件；综合素质扎实，热爱设计行业；\n2、对主流AIGC设计工","jdComplete":false,"sourceStatus":null},{"id":"tencent:1177660287764272128","sourceKey":"tencent","company":"腾讯","title":"用户研究","city":"深圳总部/北京","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1177660287764272128","duty":"1、从研究需求出发，与业务方沟通并明确研究目的，完成项目的研究设计；\n2、负责跟踪并研究行业动态及用户行为趋势，通过定量和定性研究方法，并结合AI驱动的数据分析，深入挖掘用户需求，为产品迭代和创新提供数据支持和策略建议；\n3、负责研究项目的执行与推进，探索AI在用户研究各环节的提效应用；\n4、跟进研究成果在业务方的落地，持续迭代研究方法论，保持对AI+用研前沿趋势的敏锐关注。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n熟悉定性及定量的用户研究方法，如：问卷调查、用户访谈、可用性测试、启发式评估、眼动测试等。\n\n其他：\n1、具备大局观，逻辑思维能力强，主动性高，有高效的执行力；\n2、具备优秀的理解、沟通与协调能力，有一定的文字表达能力；\n3、国家英语四级及以上水平。\n3、对AI驱动的用户研究方法有兴趣和学习意愿。","description":"你的招式千变万化，无数业内高手与你对决高下，\n在这场以用户价值为依归的擂台上，你直击亿万心灵。\n\n岗位描述\n1、从研究需求出发，与业务方沟通并明确研究目的，完成项目的研究设计；\n2、负责跟踪并研究行业动态及用户行为趋势，通过定量和定性研究方法，并结合AI驱动的数据分析，深入挖掘用户需求，为产品迭代和创新提供数据支持和策略建议；\n3、负责研究项目的执行与推进，探索AI在用户研究各环节的提效应用；\n4、跟进研究成果在业务方的落地，持续迭代研究方法论，保持对AI+用研前沿趋势的敏锐关注。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n熟悉定性及定量的用户研究方法，如：问卷调查、用户访谈、可用性测试、启发式评估、眼动测试等。\n\n其他：\n1、具备大局观，逻辑思维能力强，主动性高，有高效的执行力；","jdComplete":false,"sourceStatus":null},{"id":"tencent:1177660287764272129","sourceKey":"tencent","company":"腾讯","title":"交互设计","city":"深圳总部/上海","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1177660287764272129","duty":"1、负责参与公司互联网类产品跨端多场景的交互设计，包括传统GUI交互和AI驱动的新型交互范式（对话式交互、主动式智能推荐、生成式UI等）；\n2、参与产品需求讨论，定义AI时代的人机交互框架，输出符合设计原则及用户场景的交互设计方案；\n3、负责建立产品的用户体验指标和数据分析体系，以用户为中心持续优化产品可用性，关注AI交互的独特体验指标；\n4、负责建立和维护用户体验标准及设计规范，沉淀AI交互设计方法论；\n5、保持对AI交互前沿趋势（LLM交互设计、Agent交互范式、多模态交互等）的敏锐关注。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、工业设计、交互设计、计算机、人机交互等相关专业本科及以上学历；\n2、熟悉体验设计的基本流程和方法论。\n\n其他：\n1、具备大局观，逻辑思维能力强，主动性高，具备优秀的理解、沟通与协调能力，有一定的文字表达能力；\n2、富有创造力和激情，热衷于互联网和AI产品，喜爱动手实践，乐于尝试不同的产品。","description":"用户需求、使用场景、商业目标、技术限制是你的支点，\n你将撬动及改变亿万级用户的使用体验！\n\n岗位描述\n1、负责参与公司互联网类产品跨端多场景的交互设计，包括传统GUI交互和AI驱动的新型交互范式（对话式交互、主动式智能推荐、生成式UI等）；\n2、参与产品需求讨论，定义AI时代的人机交互框架，输出符合设计原则及用户场景的交互设计方案；\n3、负责建立产品的用户体验指标和数据分析体系，以用户为中心持续优化产品可用性，关注AI交互的独特体验指标；\n4、负责建立和维护用户体验标准及设计规范，沉淀AI交互设计方法论；\n5、保持对AI交互前沿趋势（LLM交互设计、Agent交互范式、多模态交互等）的敏锐关注。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、工业设计、交互设计、计算机、人机交互等相","jdComplete":false,"sourceStatus":null},{"id":"tencent:1188988696721092608","sourceKey":"tencent","company":"腾讯","title":"产品策划","city":"深圳总部/北京/上海/广州/成都","category":"产品","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1188988696721092608","duty":"1、负责产品规划和方案设计，持续打磨产品功能和用户体验，提高产品的市场竞争力，追求用户体验、商业价值提升；思考AI/大模型技术如何为用户创造增量价值，持续打磨产品功能和智能体验；\n2、深入了解行业动态、技术演进和竞争环境，估产品的市场表现，优化产品策略，敏锐捕捉AI重塑产品形态的机会窗口；\n3、负责构建产品业务数据监控体系，通过实验设计、A/B测试和AI辅助的用户洞察等手段，挖掘真实需求；\n4、负责跟进产品开发进度，与技术团队紧密协同，确保产品按计划、高质量上线；理解AI技术的能力边界，推动AI功能的高质量落地；\n5、收集和分析产品上线后的用户反馈和数据，推动产品持续迭代优化。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、对开发、测试、运营、设计有一定了解，对AI/大模型技术有基本认知和好奇心；\n2、关注AI产品趋势，能独立思考“AI如何让产品变得更好”。\n\n其他：\n1、优秀的创造力、想象力、逻辑思维与系统分析能力，突出的文字组织能力和沟通能力；\n2、对互联网产品极度热爱，，怀揣着做出最优秀互联网产品的梦想，具备敏捷的洞察和思维能力，并且有把思考变为现实以满足用户需求的勇气和能力。","description":"在这里，以用户为初心，\n在这里，做影响亿万用户的产品，\n下一个伟大，由你开始！\n\n岗位描述\n1、负责产品规划和方案设计，持续打磨产品功能和用户体验，提高产品的市场竞争力，追求用户体验、商业价值提升；思考AI/大模型技术如何为用户创造增量价值，持续打磨产品功能和智能体验；\n2、深入了解行业动态、技术演进和竞争环境，估产品的市场表现，优化产品策略，敏锐捕捉AI重塑产品形态的机会窗口；\n3、负责构建产品业务数据监控体系，通过实验设计、A/B测试和AI辅助的用户洞察等手段，挖掘真实需求；\n4、负责跟进产品开发进度，与技术团队紧密协同，确保产品按计划、高质量上线；理解AI技术的能力边界，推动AI功能的高质量落地；\n5、收集和分析产品上线后的用户反馈和数据，推动产品持续迭代优化。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工","jdComplete":false,"sourceStatus":null},{"id":"tencent:1199423750186201088","sourceKey":"tencent","company":"腾讯","title":"算法-多模态方向","city":"深圳总部/北京/上海/广州/成都","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1199423750186201088","duty":"作为计算机多模态方向的研究工程师，你可以：\n1、研究和开发多模态处理算法和模型的研究与开发，包括但不限于：图像、视频、3D生成、声学信号的理解与生成、多模态信息和文本信息的对齐和整合；\n2、设计和优化现有算法，提高性能和准确性，确保高质量的用户体验；\n3、深入调研和关注多模态/NLP/CV等方向的前沿技术，及时将新技术应用到产品中。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"对一个研究者来说，\n丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，\n而你正是其中一员！\n\n岗位描述\n作为计算机多模态方向的研究工程师，你可以：\n1、研究和开发多模态处理算法和模型的研究与开发，包括但不限于：图像、视频、3D生成、声学信号的理解与生成、多模态信息和文本信息的对齐和整合；\n2、设计和优化现有算法，提高性能和准确性，确保高质量的用户体验；\n3、深入调研和关注多模态/NLP/CV等方向的前沿技术，及时将新技术应用到产品中。\n\n岗位要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/","jdComplete":false,"sourceStatus":null},{"id":"tencent:1200791473415778304","sourceKey":"tencent","company":"腾讯","title":"后台开发","city":"深圳总部/北京/上海/广州/成都/杭州","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1200791473415778304","duty":"负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。\n1、深入理解业务需求和产品设计，高效地实现并优化产品功能；\n2、持续优化架构，提升关键服务和基础设施的稳定性与可用性，关注AI在智能运维、故障预测等领域的应用；\n3、通过引入AI编程工具和自动化流程，显著提升团队的开发效率和代码质量；\n4、通过与产品和前端工程师的紧密合作，共同推进产品的迭代与优化，参与AI能力在后端的集成与落地；\n5、对线上问题进行快速定位并解决，探索利用AI进行智能故障诊断和性能优化；\n6、参与新技术的研究和探索，特别关注AI/大模型技术在后端架构中的应用，为团队的技术进步和产品创新提供支持。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、扎实的编程能力，熟练掌握C/C++/Java/Go等其中一门开发语言；\n2、TCP/UDP网络协议及相关编程、进程间通讯编程；专业软件知识，包括算法、操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全等。\n3、有一定了解的：Python、Shell等脚本语言；MySQL及SQL语言、编程；NoSQL, Key-value存储原理。","description":"你是腾讯产品「背后」的英雄， \n打造出更稳定安全、高效可靠的后台支撑体系， \n守护海量用户的笑容！\n\n岗位描述\n负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。\n1、深入理解业务需求和产品设计，高效地实现并优化产品功能；\n2、持续优化架构，提升关键服务和基础设施的稳定性与可用性，关注AI在智能运维、故障预测等领域的应用；\n3、通过引入AI编程工具和自动化流程，显著提升团队的开发效率和代码质量；\n4、通过与产品和前端工程师的紧密合作，共同推进产品的迭代与优化，参与AI能力在后端的集成与落地；\n5、对线上问题进行快速定位并解决，探索利用AI进行智能故障诊断和性能优化；\n6、参与新技术的研究和探索，特别关注AI/大模型技术在后端架构中的应用，为团队的技术进步和产品创新提供支持。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断","jdComplete":false,"sourceStatus":null},{"id":"tencent:1200889496565214208","sourceKey":"tencent","company":"腾讯","title":"算法-自然语言处理方向","city":"深圳总部/北京/上海/广州/成都","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1200889496565214208","duty":"作为自然语言处理方向的研究工程师，你可以：\n1、负责自然语言处理的算法研发，包括但不限于语义分析、意图识别、人机对话、语义挖掘、机器翻译、知识图谱、命名实体识别等；\n2、负责对话系统，尤其是任务导向型对话系统的技术研究，包括自然语言理解、对话状态跟踪、对话策略学习、自然语言生成、encoder-decoder模型等；\n3、负责知识图谱相关关键技术研究，解决知识图谱和自然语言深层次表示、理解与计算问题；\n4、负责NLP前沿问题的研究，结合未来实际应用场景，提供技术解决方案。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握NLP基础理论和算法，在一个或多个领域（如对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等）能够独立开展研发工作；\n3、熟悉至少一种编程语言，包括但不限于java、C/C++、C#、python等；\n4、熟练使用一种或几种深度学习框架（如tensorflow、caffe、mxnet、pytorch等）。","description":"对一个研究者来说，\n丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，\n而你正是其中一员！\n\n岗位描述\n作为自然语言处理方向的研究工程师，你可以：\n1、负责自然语言处理的算法研发，包括但不限于语义分析、意图识别、人机对话、语义挖掘、机器翻译、知识图谱、命名实体识别等；\n2、负责对话系统，尤其是任务导向型对话系统的技术研究，包括自然语言理解、对话状态跟踪、对话策略学习、自然语言生成、encoder-decoder模型等；\n3、负责知识图谱相关关键技术研究，解决知识图谱和自然语言深层次表示、理解与计算问题；\n4、负责NLP前沿问题的研究，结合未来实际应用场景，提供技术解决方案。\n\n岗位要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握NLP基础理论和","jdComplete":false,"sourceStatus":null},{"id":"tencent:1200889496565214209","sourceKey":"tencent","company":"腾讯","title":"商务拓展","city":"深圳总部/北京/广州","category":"市场","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1200889496565214209","duty":"1、行业洞察：专精自己的细分行业，深度接触行业内各层级、各类型业务，敏锐反馈行业变化、精准找出对应解法；\n2、熟悉同类产品业务与自身业务的差异、优劣势，并关注市场对同类产品、自身业务的反馈，实操角度分析业务未来走向；\n3、客情建设和商机拓展，产品和技术价值传递，做好业务支持；\n4、协同各部门推进项目，实现项目从计划到落地、后期维护的全方位护航；\n5、通过对市场和客户需求的分析理解，协助产品改进或导入新产品策略，确保业务竞争力的持续提升。","requirements":"1、综合素质优秀，热爱互联网，熟悉互联网的主要发展方向和概念并有敏锐的市场意识；\n2、具有杰出的人际交往技巧，优秀的沟通协调能力及谈判能力，擅于合作，抗压能力强；\n3、为人正直，工作积极主动并具备高效的分析和执行能力，学习能力强，有强烈的责任心；\n4、抱有公司内创业的精神，对自身项目有高度的主人翁意识，并时刻保持业务敏感度。","description":"你是聚焦行业，洞察机遇的观察者，\n是关注客户，懂他人之所需的好伙伴，\n是并肩作战，协同拓展业务的老战友，\n来腾讯，做商务拓展人！\n\n岗位描述\n1、行业洞察：专精自己的细分行业，深度接触行业内各层级、各类型业务，敏锐反馈行业变化、精准找出对应解法；\n2、熟悉同类产品业务与自身业务的差异、优劣势，并关注市场对同类产品、自身业务的反馈，实操角度分析业务未来走向；\n3、客情建设和商机拓展，产品和技术价值传递，做好业务支持；\n4、协同各部门推进项目，实现项目从计划到落地、后期维护的全方位护航；\n5、通过对市场和客户需求的分析理解，协助产品改进或导入新产品策略，确保业务竞争力的持续提升。\n\n岗位要求\n1、综合素质优秀，热爱互联网，熟悉互联网的主要发展方向和概念并有敏锐的市场意识；\n2、具有杰出的人际交往技巧，优秀的沟通协调能力及谈判能力，擅于合作，抗压能力强；\n3、为人正直，工作积极主动并具备高效的分","jdComplete":false,"sourceStatus":null},{"id":"tencent:1200889496565214210","sourceKey":"tencent","company":"腾讯","title":"技术研究-高性能计算方向","city":"深圳总部/北京/上海/广州","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1200889496565214210","duty":"包含GPU、网络、大模型框架等细分方向。\n\n1、针对业务需求，解决算力瓶颈、通信延迟、分布式系统扩展性等问题；\n2、协同算法、硬件及运维团队，构建高效、稳定的计算基础设施。\n\n1）GPU方向：研究GPU集群的调度策略，优化资源利用率。探索混合精度计算、模型量化等GPU加速技术；\n2）网络方向：设计低延迟、高吞吐的分布式网络架构（如InfiniBand/RoCE/DPU）。优化MPI、NCCL等通信库性能，解决大规模集群中的网络拥塞问题；\n3）大模型工程框架方向：开发或优化大模型训练框架（如PyTorch/TensorFlow/DeepSpeed/Megatron-LM），设计分布式训练策略（模型并行、流水线并行、混合并行），提升千亿级参数模型的训练效率。研究训练加速技术（梯度压缩、显存优化、动态计算图调度）。","requirements":"1、扎实的计算机体系结构基础，熟悉并行计算、数据密集型系统设计；\n2、良好的数学基础（线性代数、数值分析、算法复杂度优化）。","description":"对一个研究者来说， 丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要， 而你正是其中一员！\n\n岗位描述\n包含GPU、网络、大模型框架等细分方向。\n\n1、针对业务需求，解决算力瓶颈、通信延迟、分布式系统扩展性等问题；\n2、协同算法、硬件及运维团队，构建高效、稳定的计算基础设施。\n\n1）GPU方向：研究GPU集群的调度策略，优化资源利用率。探索混合精度计算、模型量化等GPU加速技术；\n2）网络方向：设计低延迟、高吞吐的分布式网络架构（如InfiniBand/RoCE/DPU）。优化MPI、NCCL等通信库性能，解决大规模集群中的网络拥塞问题；\n3）大模型工程框架方向：开发或优化大模型训练框架（如PyTorch/TensorFlow/DeepSpeed/Megatron-LM），设计分布式训练策略（模型并行、流水线并行、混合并行），提升千亿级参数模型的训练效率。研究训练加速技术（梯度压","jdComplete":false,"sourceStatus":null},{"id":"tencent:1208929078888320000","sourceKey":"tencent","company":"腾讯","title":"算法-多模态方向","city":"北京","category":"技术","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1208929078888320000","duty":"作为计算机多模态方向的研究工程师，你可以：\n1、研究和开发多模态处理算法和模型的研究与开发，包括但不限于：图像、视频、3D生成、声学信号的理解与生成、多模态信息和文本信息的对齐和整合；\n2、设计和优化现有算法，提高性能和准确性，确保高质量的用户体验；\n3、深入调研和关注多模态/NLP/CV等方向的前沿技术，及时将新技术应用到产品中。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/C++ 编程，熟悉 Shell/Python/Matlab 至少一种编程语言。","description":"对一个研究者来说，\n丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，\n而你正是其中一员！\n\n岗位描述\n作为计算机多模态方向的研究工程师，你可以：\n1、研究和开发多模态处理算法和模型的研究与开发，包括但不限于：图像、视频、3D生成、声学信号的理解与生成、多模态信息和文本信息的对齐和整合；\n2、设计和优化现有算法，提高性能和准确性，确保高质量的用户体验；\n3、深入调研和关注多模态/NLP/CV等方向的前沿技术，及时将新技术应用到产品中。\n\n岗位要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握计算机视觉和图像处理相关的基本算法及应用，熟悉caffe、tensorflow，pytorch等至少一个深度学习框架；\n3、较强的工程实现能力，熟练掌握 C/","jdComplete":false,"sourceStatus":null},{"id":"tencent:1208929084714208256","sourceKey":"tencent","company":"腾讯","title":"算法-自然语言处理方向","city":"深圳总部","category":"技术","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1208929084714208256","duty":"作为自然语言处理方向的研究工程师，你可以：\n1、负责自然语言处理的算法研发，包括但不限于语义分析、意图识别、人机对话、语义挖掘、机器翻译、知识图谱、命名实体识别等；\n2、负责对话系统，尤其是任务导向型对话系统的技术研究，包括自然语言理解、对话状态跟踪、对话策略学习、自然语言生成、encoder-decoder模型等；\n3、负责知识图谱相关关键技术研究，解决知识图谱和自然语言深层次表示、理解与计算问题；\n4、负责NLP前沿问题的研究，结合未来实际应用场景，提供技术解决方案。","requirements":"1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握NLP基础理论和算法，在一个或多个领域（如对话系统、文本分类、语义理解、知识图谱构建、篇章理解、情感分析、自然语言生成等）能够独立开展研发工作；\n3、熟悉至少一种编程语言，包括但不限于java、C/C++、C#、python等；\n4、熟练使用一种或几种深度学习框架（如tensorflow、caffe、mxnet、pytorch等）。","description":"对一个研究者来说，\n丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要，\n而你正是其中一员！\n\n岗位描述\n作为自然语言处理方向的研究工程师，你可以：\n1、负责自然语言处理的算法研发，包括但不限于语义分析、意图识别、人机对话、语义挖掘、机器翻译、知识图谱、命名实体识别等；\n2、负责对话系统，尤其是任务导向型对话系统的技术研究，包括自然语言理解、对话状态跟踪、对话策略学习、自然语言生成、encoder-decoder模型等；\n3、负责知识图谱相关关键技术研究，解决知识图谱和自然语言深层次表示、理解与计算问题；\n4、负责NLP前沿问题的研究，结合未来实际应用场景，提供技术解决方案。\n\n岗位要求\n1、包含但不限于计算机、信息工程、模式识别、人工智能、自动化、软件工程、电子工程、统计学、应用数学、物理学/量子计算、信息安全、信号与信息处理等专业的博士和优秀硕士；\n2、熟练掌握NLP基础理论和","jdComplete":false,"sourceStatus":null},{"id":"tencent:1209171621219493888","sourceKey":"tencent","company":"腾讯","title":"技术研究-高性能计算方向","city":"深圳总部","category":"技术","channels":["campus"],"employment":"internship","talentPlan":true,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1209171621219493888","duty":"包含GPU、网络、大模型框架等细分方向。\n\n1、针对业务需求，解决算力瓶颈、通信延迟、分布式系统扩展性等问题；\n2、协同算法、硬件及运维团队，构建高效、稳定的计算基础设施。\n\n1）GPU方向：研究GPU集群的调度策略，优化资源利用率。探索混合精度计算、模型量化等GPU加速技术；\n2）网络方向：设计低延迟、高吞吐的分布式网络架构（如InfiniBand/RoCE/DPU）。优化MPI、NCCL等通信库性能，解决大规模集群中的网络拥塞问题；\n3）大模型工程框架方向：开发或优化大模型训练框架（如PyTorch/TensorFlow/DeepSpeed/Megatron-LM），设计分布式训练策略（模型并行、流水线并行、混合并行），提升千亿级参数模型的训练效率。研究训练加速技术（梯度压缩、显存优化、动态计算图调度）。","requirements":"1、扎实的计算机体系结构基础，熟悉并行计算、数据密集型系统设计；\n2、良好的数学基础（线性代数、数值分析、算法复杂度优化）。","description":"对一个研究者来说， 丰富的应用场景、全谱领域的技术积累、追求极致的氛围都很重要， 而你正是其中一员！\n\n岗位描述\n包含GPU、网络、大模型框架等细分方向。\n\n1、针对业务需求，解决算力瓶颈、通信延迟、分布式系统扩展性等问题；\n2、协同算法、硬件及运维团队，构建高效、稳定的计算基础设施。\n\n1）GPU方向：研究GPU集群的调度策略，优化资源利用率。探索混合精度计算、模型量化等GPU加速技术；\n2）网络方向：设计低延迟、高吞吐的分布式网络架构（如InfiniBand/RoCE/DPU）。优化MPI、NCCL等通信库性能，解决大规模集群中的网络拥塞问题；\n3）大模型工程框架方向：开发或优化大模型训练框架（如PyTorch/TensorFlow/DeepSpeed/Megatron-LM），设计分布式训练策略（模型并行、流水线并行、混合并行），提升千亿级参数模型的训练效率。研究训练加速技术（梯度压","jdComplete":false,"sourceStatus":null},{"id":"tencent:1210569901664899072","sourceKey":"tencent","company":"腾讯","title":"测试开发","city":"深圳总部/北京/上海/广州/成都","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1210569901664899072","duty":"1、负责开发测试工具与测试平台，帮助更快速和更有效发现缺陷；\n2、负责客户端和后台等跨平台项目质量保障，能深入理解项目实现并推进质量持续改进；\n3、负责单元测试、接口测试、协议测试、安全测试、后台测试等自动化测试工具的开发和落地执行；\n4、负责客户端性能深度分析和后台性能深度分析、安全漏洞分析，并能在此基础上实现缺陷的自动化分析与定位；\n5、探索AI前沿技术（如AI生成测试用例、智能缺陷定位与分析、自主探索式测试等），并应用到质量保障各环节，建设全流程自动化体系。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、计算机或相关专业本科及以上学历；\n2、熟练掌握C/C++/Java/Go/Python/C；\n3、理解操作系统、计算机网络、算法与数据结构等专业知识；\n4、 有一定了解的：图像处理原理或者计算机图形学；网络信息安全知识。\n\n其他：\n1、极具专研精神，主动积极的责任心、良好的团队合作精神。  \n2、对AI在测试领域的应用（AI测试生成、智能缺陷分析等）有认知和兴趣。","description":"你将一马当先，积极挑战新技术。\n大量机器与海量进程在你的指挥下井然有序， \n你就是测试开发的先锋人！\n\n岗位描述\n1、负责开发测试工具与测试平台，帮助更快速和更有效发现缺陷；\n2、负责客户端和后台等跨平台项目质量保障，能深入理解项目实现并推进质量持续改进；\n3、负责单元测试、接口测试、协议测试、安全测试、后台测试等自动化测试工具的开发和落地执行；\n4、负责客户端性能深度分析和后台性能深度分析、安全漏洞分析，并能在此基础上实现缺陷的自动化分析与定位；\n5、探索AI前沿技术（如AI生成测试用例、智能缺陷定位与分析、自主探索式测试等），并应用到质量保障各环节，建设全流程自动化体系。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、计算机或相关专业本科及以上学历；\n2、熟练掌握C/C++/Ja","jdComplete":false,"sourceStatus":null},{"id":"tencent:1210569902285656064","sourceKey":"tencent","company":"腾讯","title":"游戏客户端开发","city":"深圳总部/北京/上海/杭州","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1210569902285656064","duty":"1、针对产品需求进行框架及功能设计；\n2、实现稳定可维护的功能，并提供配套的编辑器，检查机制，性能优化，可测试支持等完整解决方案；\n3、与策划一起讨论并提出技术方案迭代优化游戏的细节体验，例如3C、AI等；\n4、在网络、性能优化、音视频、输入输出、安全、国际化、下载升级等基础技术上提供解决方案，支撑游戏所需的体验；\n5、提供构建程序包、发布、版本升级等整套技术，优化整套构建发布的效率；\n6 、探索并应用AI技术赋能游戏开发，包括利用主流AI辅助工具提升编码与管线效率，以及在实际业务（如智能行为逻辑、AIGC技术应用等）中提供AI前沿方案的工程化落地支持。","requirements":"1、计算机科学、计算机工程相关专业；\n2、熟悉算法、数据结构、操作系统等基础知识；\n3、热爱编程，至少掌握一种游戏开发常用的编程语言；\n4、具备良好的沟通表达能力和团队合作意识；\n5、对于创新和解决有挑战性的问题充满激情，有较强的学习能力、分析及解决问题能力；\n6、了解 AI 工具的基本原理与能力边界，能主动学习并将 AI 应用于研发各环节，在 AI 辅助下完成问题拆解、工程判断和验证闭环，对最终产出质量负责。","description":"玩家的一流体验，将是你努力的勋章。\n性能流畅的游戏客户端，将是你才华的成果。\n有你稳住，就能赢！\n\n岗位描述\n1、针对产品需求进行框架及功能设计；\n2、实现稳定可维护的功能，并提供配套的编辑器，检查机制，性能优化，可测试支持等完整解决方案；\n3、与策划一起讨论并提出技术方案迭代优化游戏的细节体验，例如3C、AI等；\n4、在网络、性能优化、音视频、输入输出、安全、国际化、下载升级等基础技术上提供解决方案，支撑游戏所需的体验；\n5、提供构建程序包、发布、版本升级等整套技术，优化整套构建发布的效率；\n6 、探索并应用AI技术赋能游戏开发，包括利用主流AI辅助工具提升编码与管线效率，以及在实际业务（如智能行为逻辑、AIGC技术应用等）中提供AI前沿方案的工程化落地支持。\n\n岗位要求\n1、计算机科学、计算机工程相关专业；\n2、熟悉算法、数据结构、操作系统等基础知识；\n3、热爱编程，至少掌握一种游戏开","jdComplete":false,"sourceStatus":null},{"id":"tencent:1210569906312187904","sourceKey":"tencent","company":"腾讯","title":"游戏引擎开发","city":"深圳总部/上海/广州","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1210569906312187904","duty":"负责引擎模块以及工具链部分的研发，探索AI技术在游戏引擎中的深度应用。\n1、下一代图形与渲染：迭代核心渲染管线与图形算法，打磨极致的光影效果；探索前沿图形学与AI的交叉领域，如神经渲染、AI超分、光线追踪在实时渲染中的落地；\n2、物理与动画底座：研发高拟真的碰撞检测与实时物理仿真；探索结合机器学习的物理驱动动画与角色行为系统；\n3、工业级与智能化工具链：构建高效的资源管线；推动AIGC能力与引擎编辑器的深度结合，打造加速美术生产与PCG的智能化工具流；\n4、极限性能压榨：深入操作系统与硬件底层，负责跨平台架构设计与极限性能优化；\n5、前沿技术追踪：保持对学术界和工业界最新技术的敏锐嗅觉，将其转化为引擎的实际生产力。","requirements":"1、计算机科学、计算机工程、应用数学等相关专业；\n2、扎实的\"内功\"基础：深入理解数据结构、算法、操作系统与计算机体系结构；\n3、热爱编程，至少熟练掌握一种游戏开发常用的编程语言，如C++/C#等，具备优秀的系统编程素养；\n4、对图形学、物理仿真、计算机动画、引擎架构或游戏AI等某一领域比较熟悉；\n5、熟悉/了解Unreal、Unity等主流商业引擎的架构与运作机制；\n6、良好的数学功底和英文学术/技术文档阅读能力；\n7、良好的沟通表达能力和团队合作意识；\n8、热爱游戏，对于创新和解决极具挑战性的硬核问题充满激情，有极强的学习、分析及解决问题能力。","description":"你将探索AI与引擎的深度融合，优化打磨前沿技术，攻克渲染、动画等难题，好的游戏与次世代体验，离不开你！\n\n岗位描述\n负责引擎模块以及工具链部分的研发，探索AI技术在游戏引擎中的深度应用。\n1、下一代图形与渲染：迭代核心渲染管线与图形算法，打磨极致的光影效果；探索前沿图形学与AI的交叉领域，如神经渲染、AI超分、光线追踪在实时渲染中的落地；\n2、物理与动画底座：研发高拟真的碰撞检测与实时物理仿真；探索结合机器学习的物理驱动动画与角色行为系统；\n3、工业级与智能化工具链：构建高效的资源管线；推动AIGC能力与引擎编辑器的深度结合，打造加速美术生产与PCG的智能化工具流；\n4、极限性能压榨：深入操作系统与硬件底层，负责跨平台架构设计与极限性能优化；\n5、前沿技术追踪：保持对学术界和工业界最新技术的敏锐嗅觉，将其转化为引擎的实际生产力。\n\n岗位要求\n1、计算机科学、计算机工程、应用数学等相关专业；","jdComplete":false,"sourceStatus":null},{"id":"tencent:1210646470286783488","sourceKey":"tencent","company":"腾讯","title":"后台开发","city":"深圳总部/北京/上海/广州/武汉/杭州","category":"技术","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1210646470286783488","duty":"负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。\n1、深入理解业务需求和产品设计，高效地实现并优化产品功能；\n2、持续优化架构，提升关键服务和基础设施的稳定性与可用性，关注AI在智能运维、故障预测等领域的应用；\n3、通过引入AI编程工具和自动化流程，显著提升团队的开发效率和代码质量；\n4、通过与产品和前端工程师的紧密合作，共同推进产品的迭代与优化，参与AI能力在后端的集成与落地；\n5、对线上问题进行快速定位并解决，探索利用AI进行智能故障诊断和性能优化；\n6、参与新技术的研究和探索，特别关注AI/大模型技术在后端架构中的应用，为团队的技术进步和产品创新提供支持。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、扎实的编程能力，熟练掌握C/C++/Java/Go等其中一门开发语言；\n2、TCP/UDP网络协议及相关编程、进程间通讯编程；专业软件知识，包括算法、操作系统、软件工程、设计模式、数据结构、数据库系统、网络安全等。\n3、有一定了解的：Python、Shell等脚本语言；MySQL及SQL语言、编程；NoSQL, Key-value存储原理。","description":"你是腾讯产品「背后」的英雄， \n打造出更稳定安全、高效可靠的后台支撑体系， \n守护海量用户的笑容！\n\n岗位描述\n负责实现和优化公司的产品功能，以及构建和维护关键服务与基础设施。\n1、深入理解业务需求和产品设计，高效地实现并优化产品功能；\n2、持续优化架构，提升关键服务和基础设施的稳定性与可用性，关注AI在智能运维、故障预测等领域的应用；\n3、通过引入AI编程工具和自动化流程，显著提升团队的开发效率和代码质量；\n4、通过与产品和前端工程师的紧密合作，共同推进产品的迭代与优化，参与AI能力在后端的集成与落地；\n5、对线上问题进行快速定位并解决，探索利用AI进行智能故障诊断和性能优化；\n6、参与新技术的研究和探索，特别关注AI/大模型技术在后端架构中的应用，为团队的技术进步和产品创新提供支持。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI的输出进行高质量判断","jdComplete":false,"sourceStatus":null},{"id":"tencent:1210646470286783489","sourceKey":"tencent","company":"腾讯","title":"视觉设计","city":"深圳总部/北京/广州","category":"设计","channels":["campus"],"employment":"internship","talentPlan":null,"date":null,"dateKind":null,"url":"https://join.qq.com/post_detail.html?postid=1210646470286783489","duty":"1、负责参与公司产品的视觉内容，包括UI、多媒体、品牌等设计，具备一定的跨平台及多终端设计能力；\n2、负责产品前期的概念创意，整体视觉风格的制定，推动产品实现及进行阶段性的品牌推广；\n3、负责制定设计标准及规范，保障产品体验及设计的一致性；\n4、有较好的用户体验思维，熟练使用AIGC创意工具辅助设计探索和生产，具备较强的能力扩展性。","requirements":"AI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、专业执行力：美术、设计相关专业本科或研究生，能够熟练使用Photoshop、Figma、After Effects、Illustrator、Sketch等软件；综合素质扎实，热爱设计行业；\n2、对主流AIGC设计工具有使用经验或强烈的学习兴趣，能独立思考AI如何提升设计效率与创意质量。\n\n\n其他：\n1、持续学习力：富于创新、思维灵活，并对先进的设计理念和技术有较强的理解能力；有一定的设计理论知识和对流行趋势敏锐的洞察力；\n2、团队协作力：具有良好的沟通能力和团队协作精神。","description":"在这里，\n你的设计意味着触动亿万人的情感和引领互联网时尚潮流。\n设计，不止于此！\n\n岗位描述\n1、负责参与公司产品的视觉内容，包括UI、多媒体、品牌等设计，具备一定的跨平台及多终端设计能力；\n2、负责产品前期的概念创意，整体视觉风格的制定，推动产品实现及进行阶段性的品牌推广；\n3、负责制定设计标准及规范，保障产品体验及设计的一致性；\n4、有较好的用户体验思维，熟练使用AIGC创意工具辅助设计探索和生产，具备较强的能力扩展性。\n\n岗位要求\nAI应用技能：\n善于借助AI工具拆解复杂问题、探索解决方案，并能对AI 的输出进行高质量判断，具备人机协同的工作意识和习惯。\n\n专业能力：\n1、专业执行力：美术、设计相关专业本科或研究生，能够熟练使用Photoshop、Figma、After Effects、Illustrator、Sketch等软件；综合素质扎实，热爱设计行业；\n2、对主流AIGC设计工","jdComplete":false,"sourceStatus":null}];
